export const GLOSSARY_SHARD = Object.freeze({"bitcoin-halving":{"slug":"bitcoin-halving","cat":"basics","en":"Bitcoin halving","contentLocale":"vi","term":"Bitcoin halving (sự kiện giảm một nửa)","aka":["halving","halving Bitcoin","giảm một nửa phần thưởng"],"short":"Bitcoin halving là sự kiện được lập trình sẵn, cứ mỗi 210.000 khối (khoảng 4 năm) thì phần thưởng khối cho thợ đào giảm đi một nửa, làm chậm tốc độ phát hành BTC mới.","body":[["Khi ",["Bitcoin","bitcoin"]," ra đời năm 2009, mỗi khối thưởng 50 BTC. Sau đó lần lượt giảm còn 25, 12,5 và 6,25 BTC. Đợt halving tháng 4 năm 2024 đưa phần thưởng xuống 3,125 BTC mỗi khối. Quá trình này tiếp tục cho đến khi gần đạt mức 21 triệu BTC."],"Halving không phụ thuộc vào ngày tháng mà vào số khối, nên thời điểm chính xác chỉ ước tính được. Sau mỗi lần halving, lượng BTC mới đi vào thị trường mỗi ngày giảm một nửa, còn thợ đào phải sống bằng phần thưởng thấp hơn cộng phí giao dịch.","Nhiều người theo dõi chu kỳ halving khi nói về thị trường, nhưng mối liên hệ giữa halving và giá không phải là quy luật chắc chắn. Giá còn phụ thuộc vào nhu cầu, dòng tiền vĩ mô, ETF và tâm lý thị trường."],"example":"Mạng Bitcoin tạo khoảng 144 khối mỗi ngày (24 giờ × 6 khối mỗi giờ). Với phần thưởng 6,25 BTC, lượng BTC mới mỗi ngày là khoảng 900 BTC. Sau halving 2024, phần thưởng còn 3,125 BTC nên con số này giảm còn khoảng 450 BTC mỗi ngày. Một thợ đào trước đây nhận 0,5 BTC mỗi tháng với cùng sức đào sẽ chỉ còn khoảng 0,25 BTC, chưa tính phí giao dịch.","mistakes":["Tin rằng giá chắc chắn tăng ngay sau mỗi lần halving.","Nghĩ rằng halving làm giảm số BTC bạn đang giữ, trong khi nó chỉ ảnh hưởng phần thưởng cho thợ đào.","Nhầm halving của Bitcoin với các sự kiện cùng tên của coin khác có lịch riêng."],"faq":[{"q":"Bitcoin halving diễn ra khi nào?","a":"Cứ mỗi 210.000 khối, tức khoảng 4 năm một lần. Lần gần nhất là tháng 4 năm 2024, khi phần thưởng giảm từ 6,25 xuống 3,125 BTC."},{"q":"Khi hết halving thì thợ đào lấy gì?","a":"Khi phần thưởng khối gần về 0, thợ đào sẽ phụ thuộc chủ yếu vào phí giao dịch do người dùng trả."}],"title":"Bitcoin halving là gì? Vì sao phần thưởng giảm","description":"Bitcoin halving là gì, diễn ra bao lâu một lần, ảnh hưởng thế nào tới thợ đào và lượng BTC mới mỗi ngày.","related":[["bitcoin","Bitcoin (BTC)","Bitcoin (BTC) là đồng tiền mã hóa đầu tiên, ra đời năm 2009, chạy trên blockchain riêng dùng cơ chế bằng chứng công việc và có tổng cung tối đa cố định 21 triệu đồng."],["mining","Đào coin (Crypto mining)","Đào coin (crypto mining) là quá trình dùng máy tính chuyên dụng giải bài toán mật mã để xác nhận giao dịch, thêm khối mới vào blockchain bằng chứng công việc và nhận coin mới làm phần thưởng."],["proof-of-work","Bằng chứng công việc (Proof of Work - PoW)","Bằng chứng công việc (Proof of Work, PoW) là cơ chế đồng thuận trong đó thợ đào dùng sức mạnh tính toán để giải bài toán mật mã, ai tìm ra lời giải trước sẽ được thêm khối mới và nhận thưởng."],["hash-rate","Hash rate (tốc độ băm)","Hash rate là tổng sức mạnh tính toán mà các máy đào dùng để bảo vệ một blockchain proof of work, đo bằng số phép băm mỗi giây."],["satoshi","Satoshi (sats)","Satoshi (sats) là đơn vị nhỏ nhất của Bitcoin, với 1 BTC bằng 100.000.000 satoshi, giúp bạn mua và chuyển những phần rất nhỏ của một đồng BTC."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"stop-loss":{"slug":"stop-loss","cat":"trading","en":"Stop-loss order","contentLocale":"vi","term":"Lệnh cắt lỗ (Stop-loss)","aka":["cắt lỗ","stop loss","SL","lệnh dừng lỗ"],"short":"Lệnh cắt lỗ (stop-loss) là lệnh tự động đóng vị thế khi giá chạm một mức bạn đặt trước, nhằm giới hạn khoản lỗ trong trường hợp thị trường đi ngược kỳ vọng.","body":[["Bạn đặt một giá kích hoạt (stop price). Khi giá thị trường chạm mức đó, sàn gửi một ",["lệnh thị trường","market-order"]," hoặc ",["lệnh giới hạn","limit-order"]," để thoát vị thế. Trên giao dịch hợp đồng, bạn còn có thể chọn giá kích hoạt theo giá giao dịch gần nhất hay ",["giá đánh dấu (mark price)","mark-price"],"."],["Cắt lỗ biến rủi ro mơ hồ thành con số cụ thể. Nếu bạn biết mình sẽ thoát ở đâu, bạn có thể tính kích thước lệnh sao cho mỗi lần sai chỉ mất một phần nhỏ tài khoản. Với ",["đòn bẩy","leverage"],", cắt lỗ nên nằm trước ",["giá thanh lý","liquidation-price"]," để bạn tự đóng lệnh thay vì bị sàn ",["thanh lý","liquidation"],"."],"Lệnh cắt lỗ dạng thị trường không đảm bảo giá: khi giá rơi mạnh hoặc nhảy khoảng trống, lệnh có thể khớp thấp hơn giá kích hoạt. Đặt cắt lỗ quá sát với một tài sản biến động mạnh dễ bị quét ra rồi giá quay lại."],"example":"Bạn có tài khoản 5.000 USDT và chấp nhận rủi ro tối đa 1%, tức 50 USDT mỗi lệnh. Bạn mua SOL ở 160 USDT và đặt cắt lỗ ở 152 USDT, cách 5%. Kích thước vị thế hợp lý là 50 / 0,05 = 1.000 USDT, tức 6,25 SOL. Nếu giá giảm chạm 152, lệnh kích hoạt và bạn mất khoảng 50 USDT cộng phí. Nếu giá giảm nhanh và khớp ở 150, khoản lỗ là 62,5 USDT.","mistakes":["Dời cắt lỗ xa hơn mỗi khi giá đến gần vì không muốn chấp nhận lỗ.","Đặt cắt lỗ ở mức quá sát, trong vùng dao động bình thường của giá.","Mở lệnh đòn bẩy mà không đặt cắt lỗ, để sàn thanh lý thay mình."],"faq":[{"q":"Lệnh cắt lỗ có chắc chắn khớp đúng giá không?","a":"Không. Cắt lỗ dạng thị trường đảm bảo thoát lệnh nhưng có thể khớp ở giá kém hơn khi thị trường biến động mạnh. Cắt lỗ dạng giới hạn kiểm soát giá nhưng có thể không khớp."},{"q":"Nên đặt cắt lỗ bao nhiêu phần trăm?","a":"Không có con số chung. Cắt lỗ nên đặt ở mức mà nếu giá chạm tới thì lý do vào lệnh của bạn không còn đúng, rồi tính kích thước lệnh từ đó."}],"title":"Stop-loss là gì? Cách đặt lệnh cắt lỗ","description":"Lệnh cắt lỗ (stop-loss) là gì, cách đặt giá kích hoạt, tính kích thước lệnh theo rủi ro và vì sao vẫn có thể bị trượt giá.","related":[["take-profit","Lệnh chốt lời (Take-profit)","Lệnh chốt lời (take-profit) là lệnh tự động đóng toàn bộ hoặc một phần vị thế khi giá đạt mức lợi nhuận bạn đặt trước, giúp bạn khóa lãi mà không cần theo dõi màn hình liên tục."],["stop-limit-order","Lệnh dừng giới hạn (Stop-limit)","Lệnh dừng giới hạn (stop-limit) là lệnh có hai mức giá: khi giá chạm giá kích hoạt (stop), sàn đặt một lệnh giới hạn ở giá giới hạn (limit) bạn đã chọn, thay vì một lệnh thị trường."],["trailing-stop","Lệnh cắt lỗ động (Trailing stop)","Lệnh cắt lỗ động (trailing stop) là lệnh dừng có giá kích hoạt tự động di chuyển theo giá khi giá đi đúng hướng, giữ một khoảng cách cố định, và chỉ kích hoạt khi giá đảo chiều đủ khoảng cách đó."],["position-sizing","Quản lý khối lượng vị thế (Position sizing)","Position sizing là cách xác định bạn nên mở một lệnh lớn bao nhiêu, dựa trên số tiền bạn chấp nhận mất nếu lệnh chạm cắt lỗ."],["liquidation","Thanh lý (Liquidation)","Thanh lý (hay cháy tài khoản) là khi sàn tự động đóng vị thế có đòn bẩy của bạn vì ký quỹ không còn đủ đáp ứng mức ký quỹ duy trì."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Chốt lời và cắt lỗ là kế hoạch, không phải bảo hiểm"},"coin":null,"tool":"/liquidations","cta":false},"unrealized-pnl":{"slug":"unrealized-pnl","cat":"derivatives","en":"Unrealized PnL","contentLocale":"vi","term":"Lãi lỗ chưa thực hiện (Unrealized PnL)","aka":["unrealized PnL","PnL chưa thực hiện","lãi lỗ tạm tính","uPnL"],"short":"Lãi lỗ chưa thực hiện (unrealized PnL) là khoản lãi hoặc lỗ trên giấy của một vị thế đang mở, tính theo giá hiện tại, và chỉ trở thành lãi lỗ thật khi bạn đóng vị thế.","body":[["Với ",["hợp đồng tương lai","futures-contract"],", sàn thường tính unrealized PnL theo ",["giá đánh dấu","mark-price"],", không phải ",["giá giao dịch cuối","last-price"],". Con số này thay đổi liên tục theo thị trường. Khi bạn đóng vị thế, phần đó chuyển thành lãi lỗ đã thực hiện (realized PnL) sau khi trừ phí."],["Ở chế độ ",["ký quỹ chéo","cross-margin"],", lãi chưa thực hiện có thể được dùng làm ký quỹ hỗ trợ vị thế khác, và lỗ chưa thực hiện làm giảm số dư khả dụng. Một số sàn cho phép rút hoặc dùng lãi chưa thực hiện, một số thì không; quy định này khác nhau."],["ROE hoặc tỷ suất lợi nhuận trên ký quỹ thường hiển thị cạnh PnL. Con số phần trăm này bị phóng đại bởi ",["đòn bẩy","leverage"],", nên hãy nhìn cả số tiền tuyệt đối."]],"example":["Giả sử bạn long 4 ",["ETH","ethereum"]," ở 2.800 USDT với đòn bẩy 8x, ký quỹ 1.400 USDT. Giá đánh dấu hiện là 2.870 USDT. Unrealized PnL là 4 × (2.870 - 2.800) = 280 USDT, ROE là 280 / 1.400 = 20%. Nếu bạn đóng vị thế ở 2.865 với phí taker 0,05% trên khoảng 11.460 USDT (khoảng 5,7 USDT), lãi đã thực hiện khoảng 254 USDT, chưa tính phí mở lệnh."],"mistakes":["Coi lãi chưa thực hiện như tiền đã về tài khoản.","Nhìn ROE 100% và quên rằng nó chỉ là phần trăm trên ký quỹ nhỏ.","Không tính phí đóng lệnh và funding vào lợi nhuận cuối cùng."],"faq":[{"q":"Unrealized PnL là gì?","a":"Là lãi lỗ tạm tính của vị thế đang mở. Nó chỉ trở thành lãi lỗ thật khi bạn đóng vị thế."},{"q":"Vì sao PnL trên ứng dụng khác với số tôi tự tính?","a":"Sàn thường dùng giá đánh dấu thay vì giá giao dịch cuối, và có thể đã trừ hoặc chưa trừ phí. Hãy kiểm tra cài đặt hiển thị của sàn."}],"title":"Unrealized PnL là gì? Lãi lỗ chưa thực hiện","description":"Lãi lỗ chưa thực hiện là gì, cách sàn tính unrealized PnL theo giá đánh dấu và khác lãi lỗ đã thực hiện thế nào.","related":[["mark-price","Giá đánh dấu (Mark price)","Giá đánh dấu (mark price) là giá tham chiếu mà sàn dùng để tính lãi lỗ chưa thực hiện và quyết định thanh lý, được xây dựng từ giá chỉ số của nhiều sàn spot."],["cross-margin","Ký quỹ chéo (Cross margin)","Ký quỹ chéo là chế độ trong đó toàn bộ số dư khả dụng của tài khoản được dùng chung làm ký quỹ cho các vị thế, giúp hạn chế thanh lý sớm nhưng có thể khiến bạn mất cả tài khoản."],["liquidation-price","Giá thanh lý (Liquidation price)","Giá thanh lý là mức giá đánh dấu mà tại đó vị thế có đòn bẩy của bạn sẽ bị sàn tự động đóng do ký quỹ không còn đủ."],["take-profit","Lệnh chốt lời (Take-profit)","Lệnh chốt lời (take-profit) là lệnh tự động đóng toàn bộ hoặc một phần vị thế khi giá đạt mức lợi nhuận bạn đặt trước, giúp bạn khóa lãi mà không cần theo dõi màn hình liên tục."]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"Tại sao bạn có thể bị đóng vị thế trước khi tiền ký quỹ về không?"},"coin":null,"tool":null,"cta":false},"cold-wallet":{"slug":"cold-wallet","cat":"wallets-security","en":"Cold wallet (cold storage)","contentLocale":"vi","term":"Ví lạnh (Cold wallet)","aka":["cold wallet","cold storage","lưu trữ lạnh"],"short":"Ví lạnh là cách lưu khóa riêng tư hoàn toàn ngoại tuyến, ví dụ trên ví cứng hoặc thiết bị không bao giờ kết nối mạng, để giảm tối đa rủi ro bị hack từ xa.","body":[["Ý tưởng cốt lõi của ví lạnh là ",["khóa riêng tư","private-key"]," không bao giờ chạm vào thiết bị có internet. Khi cần gửi tiền, giao dịch được tạo trên máy online nhưng chữ ký được thực hiện bên trong thiết bị ngoại tuyến, rồi mới phát lên ",["blockchain","blockchain"],"."],["Các hình thức phổ biến gồm ",["ví cứng","hardware-wallet"]," như Ledger, Trezor, máy tính cách ly mạng, hoặc ví giấy (nay ít được khuyên dùng). Các sàn lớn cũng giữ phần lớn tiền khách hàng trong ví lạnh, thường kết hợp đa chữ ký."],["Ví lạnh chống được mã độc và hack từ xa, nhưng không chống được việc bạn tự đưa ",["cụm từ khôi phục","seed-phrase"]," cho kẻ lừa đảo, hay ký nhầm một giao dịch độc hại. Bản sao lưu cụm từ cũng phải được cất ngoại tuyến."]],"example":["Giả sử bạn nắm giữ 0,5 ",["BTC","bitcoin"]," lâu dài và chỉ giao dịch vài lần mỗi năm. Bạn chuyển 0,5 BTC vào ví cứng, chép 24 từ khôi phục lên tấm kim loại và cất ở hai nơi khác nhau. Khi muốn bán 0,1 BTC, bạn cắm ví cứng, ",["xác nhận","block-confirmations"]," địa chỉ nhận trên màn hình thiết bị, bấm nút ký, và 0,4 BTC còn lại vẫn nằm yên ngoại tuyến."],"mistakes":["Mua ví cứng đã qua sử dụng hoặc đã được ai đó cài sẵn cụm từ khôi phục.","Lưu cụm từ khôi phục của ví lạnh vào ghi chú điện thoại, biến nó thành ví nóng.","Không thử khôi phục ví bằng bản sao lưu trước khi gửi số tiền lớn vào."],"faq":[{"q":"Ví lạnh có bị hack không?","a":"Rất khó bị hack từ xa vì khóa không lên mạng. Rủi ro chính đến từ việc lộ cụm từ khôi phục, thiết bị giả và ký nhầm giao dịch."},{"q":"Có cần ví lạnh nếu số tiền nhỏ?","a":"Không bắt buộc. Nhiều người bắt đầu dùng ví lạnh khi số tiền đủ lớn để giá một chiếc ví cứng là hợp lý so với rủi ro mất tiền."}],"title":"Ví lạnh (cold wallet) là gì? Cách lưu trữ lạnh","description":"Ví lạnh là gì, khác ví nóng thế nào, các loại cold storage phổ biến và những sai lầm khiến ví lạnh mất tác dụng.","related":[["hot-wallet","Ví nóng (Hot wallet)","Ví nóng là ví crypto có khóa riêng tư nằm trên thiết bị hoặc máy chủ kết nối internet, giúp giao dịch nhanh nhưng dễ bị tấn công từ xa hơn ví lạnh."],["hardware-wallet","Ví cứng (Hardware wallet)","Ví cứng là thiết bị vật lý nhỏ chuyên lưu khóa riêng tư ngoại tuyến và ký giao dịch bên trong thiết bị, nên khóa không bao giờ lộ ra máy tính hay điện thoại."],["seed-phrase","Cụm từ khôi phục (Seed phrase)","Cụm từ khôi phục là chuỗi 12 hoặc 24 từ tiếng Anh dùng để tạo lại toàn bộ khóa riêng tư của ví, nên ai có nó là có toàn quyền với tài sản trong ví."],["multisig-wallet","Ví đa chữ ký (Multisig wallet)","Ví đa chữ ký là ví cần nhiều khóa riêng tư cùng ký, ví dụ 2 trên 3 khóa, thì giao dịch mới được thực hiện, giúp không một khóa đơn lẻ nào có thể tự di chuyển tài sản."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin của tôi ở đâu: Sàn giao dịch và ví khác nhau thế nào?"},"coin":null,"tool":null,"cta":false},"rug-pull":{"slug":"rug-pull","cat":"wallets-security","en":"Rug pull","contentLocale":"vi","term":"Rug pull (Rút thảm)","aka":["rug pull","rút thảm","rug"],"short":"Rug pull là khi đội ngũ dự án crypto đột ngột rút thanh khoản, bán tháo token hoặc biến mất cùng tiền của nhà đầu tư, khiến giá token gần như về 0.","body":[["Kiểu phổ biến nhất xảy ra với token mới trên ",["DEX","dex"],": nhà phát triển tạo token, ghép với ",["ETH","ethereum"],", BNB hay SOL thành ",["pool thanh khoản","liquidity-pool"],", quảng bá rầm rộ, rồi rút toàn bộ pool. Người mua còn token trong tay nhưng không còn gì để bán ra."],"Các biến thể khác gồm: hợp đồng có hàm cho phép đội ngũ in thêm token vô hạn, chặn người khác bán (honeypot), đặt thuế bán 99%, hoặc ví đội ngũ nắm phần lớn nguồn cung và xả dần.",["Những điểm nên kiểm tra trước khi mua token mới: ",["thanh khoản","liquidity"]," có bị khóa không và khóa bao lâu, quyền chủ sở hữu hợp đồng đã từ bỏ chưa, tỷ lệ token tập trung ở vài ví, và có thể bán thử một lượng nhỏ hay không. Không bước nào đảm bảo an toàn tuyệt đối."]],"example":["Giả sử một ",["memecoin","memecoin"]," mới có pool 50 ETH đối ứng với token trên DEX. Bạn mua bằng 1 ETH khi cộng đồng đang sôi động. Hai ngày sau, ví của nhà phát triển rút cả pool, lấy đi khoảng 120 ETH đã tích lũy từ người mua. Giá token rơi hơn 99%, số token của bạn chỉ còn bán được vài phần nghìn ETH."],"mistakes":["Mua token chỉ dựa vào lời kêu gọi trong nhóm Telegram mà không kiểm tra hợp đồng và thanh khoản.","Nghĩ rằng giá tăng mạnh trong vài giờ đầu là dấu hiệu dự án đáng tin.","Tin rằng thanh khoản “đã khóa” là đảm bảo tuyệt đối, trong khi đội ngũ vẫn có thể xả token họ nắm giữ."],"faq":[{"q":"Rug pull có phạm pháp không?","a":"Ở nhiều quốc gia, hành vi lừa đảo chiếm đoạt tài sản là vi phạm pháp luật, nhưng việc truy cứu phụ thuộc vào luật từng nước và khả năng xác định danh tính đội ngũ ẩn danh."},{"q":"Làm sao kiểm tra một token có nguy cơ rug pull?","a":"Xem thanh khoản có khóa không, hợp đồng còn quyền in thêm hay chặn bán không, và phân bổ token giữa các ví. Các công cụ quét hợp đồng giúp phát hiện dấu hiệu, nhưng không thay được sự thận trọng."}],"title":"Rug pull là gì? Dấu hiệu dự án crypto rút thảm","description":"Rug pull là gì, các kiểu rút thảm phổ biến với token mới trên DEX và những điểm cần kiểm tra trước khi mua memecoin.","related":[["memecoin","Memecoin (meme coin)","Memecoin là đồng tiền mã hóa lấy cảm hứng từ meme, trò đùa hay văn hóa mạng, giá trị chủ yếu đến từ cộng đồng và sự chú ý thay vì sản phẩm hay dòng tiền thực."],["liquidity-pool","Pool thanh khoản (Liquidity pool)","Pool thanh khoản là kho token được khóa trong hợp đồng thông minh, do nhiều người cùng góp vào, để người khác giao dịch, vay hoặc swap, đổi lại người góp nhận một phần phí."],["token-approval","Cấp quyền token (Token approval)","Cấp quyền token là thao tác cho phép một hợp đồng thông minh được chi tiêu một lượng token nhất định trong ví của bạn, bắt buộc trước khi swap hay gửi token vào nhiều ứng dụng DeFi."],["dex","Sàn phi tập trung (DEX)","Sàn phi tập trung (DEX) là nơi giao dịch crypto trực tiếp từ ví của bạn qua hợp đồng thông minh, không cần nạp tiền vào tài khoản của một công ty trung gian."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Có người bảo giúp bạn kiếm tiền. Hãy xem họ đòi hỏi điều gì trước đã."},"coin":null,"tool":"/topics/meme-coins","cta":false},"oracle":{"slug":"oracle","cat":"defi","en":"Blockchain oracle","contentLocale":"vi","term":"Oracle (Nguồn dữ liệu blockchain)","aka":["oracle","price oracle","oracle giá"],"short":"Oracle là dịch vụ đưa dữ liệu bên ngoài như giá tài sản, kết quả sự kiện hay số ngẫu nhiên vào blockchain để hợp đồng thông minh sử dụng.","body":[[["Hợp đồng thông minh","smart-contract"]," không tự đọc được giá ",["BTC","bitcoin"]," trên các sàn. Giao thức cho vay cần giá để tính ",["thanh lý","liquidation"],", ",["DEX phái sinh","perp-dex"]," cần giá để tính lãi lỗ, ",["stablecoin thế chấp crypto","crypto-backed-stablecoin"]," cần giá để biết tài sản đảm bảo còn đủ không. Oracle như Chainlink, Pyth gom giá từ nhiều nguồn, tổng hợp và ghi lên chuỗi."],["Oracle là điểm yếu nhạy cảm. Nếu giao thức lấy giá từ một pool ",["DEX","dex"]," mỏng, kẻ tấn công có thể dùng flash loan đẩy giá trong pool đó, khiến hợp đồng tin vào giá sai và cho vay quá mức hoặc thanh lý sai. Oracle tốt dùng nhiều nguồn, giá trung bình theo thời gian và giới hạn độ lệch."],"Với người dùng, giá oracle có thể khác giá bạn thấy trên một sàn cụ thể, và thanh lý trên DeFi thường căn cứ vào giá oracle chứ không phải giá trên sàn bạn đang xem."],"example":"Giả sử bạn vay trên một giao thức có ngưỡng thanh lý khi ETH xuống 1.800 USD. Trên một sàn nhỏ, ETH chớp xuống 1.780 USD trong vài giây vì lệnh bán lớn. Oracle tổng hợp từ nhiều sàn lớn báo 1.850 USD, nên vị thế của bạn chưa bị thanh lý. Nếu giao thức chỉ dùng giá từ sàn nhỏ kia, bạn đã bị thanh lý vì một cú râu nến cục bộ.","mistakes":["Chỉ theo dõi giá trên một sàn mà không biết giao thức dùng oracle nào để thanh lý.","Gửi tiền vào giao thức mới dùng giá từ một pool DEX mỏng làm oracle.","Nghĩ rằng oracle là một blockchain riêng chứ không phải một dịch vụ cung cấp dữ liệu."],"faq":[{"q":"Vì sao blockchain cần oracle?","a":"Blockchain chỉ biết dữ liệu trên chuỗi. Để dùng giá thị trường hay sự kiện ngoài đời, hợp đồng cần một nguồn đáng tin đưa dữ liệu đó vào."},{"q":"Tấn công oracle là gì?","a":"Là khi kẻ gian thao túng nguồn giá mà giao thức tin dùng, thường bằng vốn lớn hoặc flash loan, để vay quá mức hoặc rút tài sản với giá sai."}],"title":"Oracle là gì trong blockchain? Vai trò trong DeFi","description":"Oracle blockchain là gì, vì sao DeFi cần oracle giá như Chainlink, tấn công oracle diễn ra thế nào và ảnh hưởng tới thanh lý.","related":[["smart-contract","Hợp đồng thông minh (Smart contract)","Hợp đồng thông minh (smart contract) là chương trình được triển khai trên blockchain, tự động thực hiện các điều kiện đã lập trình khi có giao dịch gọi tới mà không cần bên trung gian."],["defi-lending","Cho vay DeFi (DeFi lending)","Cho vay DeFi là việc gửi crypto vào giao thức như Aave để nhận lãi, hoặc thế chấp crypto để vay tài sản khác, toàn bộ do hợp đồng thông minh quản lý thay cho ngân hàng."],["index-price","Giá chỉ số (Index price)","Giá chỉ số (index price) là giá trung bình có trọng số của một tài sản trên nhiều sàn spot lớn, được dùng làm tham chiếu cho giá đánh dấu và funding rate."],["flash-loan","Flash loan (Vay nhanh)","Flash loan là khoản vay không cần thế chấp trong DeFi, với điều kiện vay và trả cả gốc lẫn phí trong cùng một giao dịch; nếu không trả đủ, toàn bộ giao dịch bị hủy."]],"lesson":null,"coin":{"slug":"chainlink","name":"Chainlink","symbol":"LINK"},"tool":null,"cta":false},"launchpad":{"slug":"launchpad","cat":"exchange-features","en":"Launchpad (token sale)","contentLocale":"vi","term":"Launchpad (mở bán token)","aka":["launchpad","IEO","mở bán token trên sàn","token sale"],"short":"Launchpad là nền tảng mở bán token mới, nơi người dùng đăng ký mua token của dự án trước khi niêm yết, thường với giá cố định và số lượng phân bổ có hạn.","body":[["Trên ",["sàn tập trung","centralized-exchange"],", Launchpad thường tổ chức dưới dạng IEO. Người dùng cam kết một lượng token như BNB hay ",["USDT","usdt"]," trong thời gian đăng ký. Nếu tổng cam kết vượt số token mở bán, mỗi người được phân bổ theo tỷ lệ, phần dư được hoàn lại."],"Ngoài sàn, còn có launchpad trên chuỗi, nơi bạn kết nối ví để mua. Loại này thường ít kiểm duyệt hơn, nên rủi ro dự án kém chất lượng hay lừa đảo cao hơn.",["Hãy đọc kỹ lịch ",["mở khóa token","token-unlock"],". Nhiều dự án chỉ mở một phần token tại thời điểm ",["niêm yết","token-listing"],", phần còn lại mở dần theo tháng. Giá sau niêm yết có thể cao hơn hoặc thấp hơn giá bán, không có gì bảo đảm."]],"example":"Giả sử một đợt Launchpad bán token trị giá 1.000.000 USDT, nhưng người dùng cam kết tổng cộng 50.000.000 USDT. Tỷ lệ phân bổ là 2%. Bạn cam kết 1.000 USDT, nhận token trị giá 20 USDT theo giá mở bán, và 980 USDT được hoàn lại. Nếu muốn có token trị giá 1.000 USDT, bạn phải cam kết khoảng 50.000 USDT, nên phần lời thực tế trên tổng vốn bị khóa thường nhỏ hơn nhiều người nghĩ.","mistakes":["Tính lợi nhuận dựa trên số tiền cam kết thay vì số token thực nhận.","Bỏ qua lịch mở khóa của đội ngũ và quỹ đầu tư.","Tham gia launchpad trên chuỗi qua đường link lạ mà không kiểm tra hợp đồng chính thức."],"faq":[{"q":"Launchpad có lời chắc không?","a":"Không. Có đợt token tăng mạnh sau niêm yết, có đợt giảm dưới giá bán. Kết quả phụ thuộc vào nhu cầu thị trường và lượng token được mở khóa."},{"q":"IEO là gì?","a":"IEO là đợt mở bán token do một sàn giao dịch tổ chức. Sàn thẩm định dự án ở một mức độ nhất định và thường niêm yết token ngay sau đợt bán."}],"title":"Launchpad là gì? Cách mở bán token IEO hoạt động","description":"Launchpad là nơi mở bán token mới trước niêm yết. Tìm hiểu cách phân bổ, hoàn tiền, lịch mở khóa và rủi ro khi tham gia.","related":[["launchpool","Launchpool","Launchpool là chương trình trên sàn cho phép bạn khóa token như BNB hay stablecoin trong một thời gian để nhận miễn phí token mới của dự án sắp niêm yết."],["token-listing","Niêm yết token (listing)","Niêm yết token là việc một sàn giao dịch chính thức thêm một token vào danh sách để người dùng có thể nạp, rút và giao dịch với các cặp nhất định."],["token-unlock","Mở khóa token (Token unlock)","Mở khóa token (token unlock) là thời điểm một lượng token trước đây bị khóa theo lịch vesting được phép chuyển và bán, thường là phần của đội ngũ, nhà đầu tư hoặc quỹ dự án."],["airdrop","Airdrop","Airdrop là việc một dự án phát token miễn phí vào ví của người dùng đủ điều kiện, thường để thưởng người dùng sớm, phân phối token rộng hơn hoặc quảng bá dự án."]],"lesson":null,"coin":null,"tool":"/activities","cta":false},"sub-account":{"slug":"sub-account","cat":"exchange-features","en":"Sub-account","contentLocale":"vi","term":"Tài khoản phụ (sub-account)","aka":["sub-account","tài khoản con","subaccount"],"short":"Tài khoản phụ là tài khoản con được tạo dưới tài khoản chính trên sàn, có số dư và vị thế riêng, giúp bạn tách biệt chiến lược, rủi ro và quyền truy cập.","body":[["Hầu hết sàn lớn cho phép tạo nhiều tài khoản phụ không cần ",["KYC","kyc"]," lại, vì chúng thuộc cùng chủ tài khoản chính. Bạn có thể chuyển tiền miễn phí giữa tài khoản chính và tài khoản phụ ngay lập tức."],["Cách dùng phổ biến: một tài khoản phụ cho bot giao dịch, một cho ",["hợp đồng tương lai","futures-contract"]," ",["đòn bẩy","leverage"]," cao, một cho ",["copy trade","copy-trading"],". Nếu một chiến lược ",["bị thanh lý","liquidation"],", chỉ số tiền trong tài khoản phụ đó bị ảnh hưởng. Bạn cũng có thể tạo API key riêng cho từng tài khoản phụ với quyền hạn chế."],["Tài khoản phụ thường có giới hạn về tính năng, ví dụ không dùng được ",["P2P","p2p-trading"]," hoặc không rút trực tiếp tùy thiết lập. Số lượng tài khoản phụ tối đa và cách tính cấp phí VIP cũng khác nhau giữa các sàn."]],"example":"Giả sử bạn có 10.000 USDT trong tài khoản chính. Bạn tạo tài khoản phụ A với 2.000 USDT cho bot lưới, và tài khoản phụ B với 1.000 USDT cho futures đòn bẩy 10 lần. Một đợt biến động mạnh khiến vị thế ở B bị thanh lý, bạn mất 1.000 USDT. Bot ở A và 7.000 USDT trong tài khoản chính hoàn toàn không bị ảnh hưởng, vì mỗi tài khoản có ký quỹ riêng.","mistakes":["Cấp quyền rút tiền cho API key của tài khoản phụ dùng cho bot.","Tạo nhiều tài khoản phụ rồi quên theo dõi vị thế đang mở ở từng cái.","Nghĩ tài khoản phụ có thể dùng để có thêm lượt nhận thưởng người dùng mới."],"faq":[{"q":"Tài khoản phụ có cần KYC riêng không?","a":"Thường không, vì nó thuộc về tài khoản chính đã KYC. Một số sàn yêu cầu tài khoản chính đạt cấp xác minh nhất định mới được tạo tài khoản phụ."},{"q":"Khối lượng ở tài khoản phụ có tính vào cấp VIP không?","a":"Nhiều sàn gộp khối lượng của tài khoản phụ vào tài khoản chính để xét cấp phí, nhưng quy tắc khác nhau. Hãy xem trang phí của sàn bạn dùng."}],"title":"Tài khoản phụ là gì? Cách dùng sub-account trên sàn","description":"Tài khoản phụ giúp tách biệt chiến lược, rủi ro và API key trên sàn crypto. Tìm hiểu cách dùng, giới hạn và ví dụ cụ thể.","related":[["unified-trading-account","Tài khoản giao dịch hợp nhất (UTA)","Tài khoản giao dịch hợp nhất là loại tài khoản gộp spot, ký quỹ, hợp đồng tương lai và quyền chọn vào một ví duy nhất, cho phép dùng chung tài sản làm ký quỹ."],["isolated-margin","Ký quỹ cô lập (Isolated margin)","Ký quỹ cô lập là chế độ trong đó mỗi vị thế có một khoản ký quỹ riêng, nên nếu bị thanh lý bạn chỉ mất phần ký quỹ đã gán cho vị thế đó."],["two-factor-authentication","Xác thực hai yếu tố (2FA)","Xác thực hai yếu tố (2FA) là lớp bảo mật yêu cầu thêm một mã hoặc thiết bị ngoài mật khẩu khi đăng nhập, rút tiền hay đổi cài đặt, để kẻ chỉ có mật khẩu vẫn không vào được tài khoản."],["copy-trading","Copy trade (sao chép giao dịch)","Copy trade là tính năng cho phép bạn tự động sao chép các lệnh của một nhà giao dịch khác, gọi là trader dẫn dắt, theo tỷ lệ vốn mà bạn phân bổ."]],"lesson":null,"coin":null,"tool":null,"cta":false},"vip-tier":{"slug":"vip-tier","cat":"exchange-features","en":"VIP fee tier","contentLocale":"vi","term":"Cấp VIP (bậc phí giao dịch)","aka":["VIP tier","cấp phí VIP","bậc phí","fee tier"],"short":"Cấp VIP là hệ thống bậc phí của sàn, trong đó người dùng có khối lượng giao dịch hoặc số dư tài sản lớn hơn được hưởng mức phí maker và taker thấp hơn.","body":[["Sàn thường xét cấp VIP dựa trên ",["khối lượng giao dịch","trading-volume"]," 30 ngày, số dư tài sản, hoặc lượng token nền tảng bạn nắm giữ. Spot và ",["hợp đồng tương lai","futures-contract"]," có thể có bảng bậc riêng. Mỗi bậc cao hơn giảm phí một chút, ở bậc rất cao ",["phí maker","maker-taker-fees"]," có thể bằng 0 hoặc âm."],["Với người giao dịch thông thường, khoảng cách từ cấp thường lên VIP 1 có thể đã cần khối lượng hàng triệu USD mỗi tháng. Vì vậy với phần lớn người dùng, cách giảm phí thực tế hơn là đặt lệnh maker, dùng token sàn để trừ phí nếu có, hoặc nhận hoàn phí qua ",["mã giới thiệu","referral-code"],"."],"Ngưỡng, mức phí và cách tính khác nhau giữa các sàn và thay đổi theo thời gian. Hãy xem trang biểu phí chính thức thay vì dựa vào ảnh chụp cũ."],"example":["Giả sử một sàn có phí taker 0,05% ở cấp thường và 0,04% ở VIP 1, với điều kiện khối lượng hợp đồng tương lai 30 ngày từ 15 triệu ",["USDT","usdt"],". Nếu bạn giao dịch đúng 15 triệu USDT mỗi tháng bằng lệnh taker, phí ở cấp thường là 7.500 USDT, ở VIP 1 là 6.000 USDT, tiết kiệm 1.500 USDT. Nhưng nếu bạn chỉ giao dịch 300.000 USDT mỗi tháng, chênh lệch tương đương chỉ là 30 USDT. Các con số chỉ minh họa."],"mistakes":["Tăng khối lượng giao dịch quá mức chỉ để đạt VIP, làm tăng rủi ro thua lỗ.","So sánh phí giữa các sàn mà không để ý mình đang ở cấp nào.","Quên rằng cấp VIP được xét lại định kỳ và có thể bị hạ khi khối lượng giảm."],"faq":[{"q":"Làm sao lên cấp VIP trên sàn?","a":"Thường bằng cách đạt khối lượng giao dịch 30 ngày hoặc số dư tài sản theo ngưỡng của sàn. Một số sàn có chương trình dùng thử VIP cho người chuyển từ sàn khác."},{"q":"Phí maker âm nghĩa là gì?","a":"Nghĩa là sàn trả tiền cho bạn khi lệnh maker của bạn được khớp. Mức này thường chỉ dành cho bậc VIP rất cao hoặc nhà tạo lập thị trường."}],"title":"Cấp VIP là gì? Bậc phí giao dịch trên sàn crypto","description":"Cấp VIP giúp giảm phí maker và taker theo khối lượng hoặc số dư. Tìm hiểu cách xét cấp, ví dụ tính tiết kiệm và lưu ý.","related":[["maker-taker-fees","Phí maker và phí taker (Maker/Taker fee)","Phí maker và phí taker là hai mức phí giao dịch khác nhau: maker trả phí khi lệnh của bạn nằm chờ trên sổ lệnh và tạo thêm thanh khoản, taker trả phí khi lệnh của bạn khớp ngay với lệnh có sẵn."],["referral-code","Mã giới thiệu (hoàn phí giao dịch)","Mã giới thiệu là mã bạn nhập khi đăng ký sàn để liên kết tài khoản với người hoặc đối tác giới thiệu, thường giúp bạn được hoàn một phần phí giao dịch hoặc nhận ưu đãi người mới."],["trading-volume","Khối lượng giao dịch (Volume)","Khối lượng giao dịch là tổng giá trị hoặc số lượng một tài sản đã được mua bán trong một khoảng thời gian, thường tính trong 24 giờ."],["market-maker","Nhà tạo lập thị trường (Market maker)","Nhà tạo lập thị trường (market maker) là cá nhân hoặc tổ chức liên tục đặt lệnh mua và lệnh bán cho một tài sản để cung cấp thanh khoản và kiếm lời từ chênh lệch giá."]],"lesson":null,"coin":null,"tool":"/rates","cta":false},"token-listing":{"slug":"token-listing","cat":"exchange-features","en":"Token listing","contentLocale":"vi","term":"Niêm yết token (listing)","aka":["listing","niêm yết","lên sàn","token listing"],"short":"Niêm yết token là việc một sàn giao dịch chính thức thêm một token vào danh sách để người dùng có thể nạp, rút và giao dịch với các cặp nhất định.","body":[[["Sàn tập trung","centralized-exchange"]," xem xét nhiều yếu tố trước khi niêm yết: đội ngũ, công nghệ, ",["thanh khoản","liquidity"],", cộng đồng, rủi ro pháp lý và kết quả kiểm toán ",["hợp đồng thông minh","smart-contract"],". Thông báo niêm yết thường ghi rõ thời gian mở nạp, mở giao dịch, mở rút và các ",["cặp giao dịch","trading-pair"],"."],["Token mới niêm yết thường ",["biến động","volatility"]," rất mạnh trong những giờ đầu vì cung cầu chưa ổn định. Nhiều sàn có cơ chế bảo vệ như giới hạn giá trong vài phút đầu hoặc nhãn cảnh báo cho token rủi ro cao."],["Trên ",["sàn phi tập trung","dex"],", bất kỳ ai cũng có thể tạo pool cho một token, nên việc có mặt trên DEX không đồng nghĩa với việc được thẩm định. Hãy kiểm tra đúng địa chỉ hợp đồng được dự án công bố."]],"example":"Giả sử sàn thông báo niêm yết token ABC lúc 15:00 với cặp ABC/USDT. Trong năm phút đầu, giá nhảy từ 0,20 lên 0,60 USDT rồi rơi xuống 0,35 USDT. Nếu bạn đặt lệnh thị trường mua 300 USDT đúng lúc giá ở 0,60, bạn nhận khoảng 500 ABC. Khi giá về 0,35, khoản đó chỉ còn 175 USDT, lỗ khoảng 42%. Dùng lệnh giới hạn và chờ giá ổn định giúp tránh mua đuổi ở đỉnh.","mistakes":["Đặt lệnh thị trường mua token mới ngay giây đầu tiên niêm yết.","Mua token trên DEX theo tên mà không kiểm tra địa chỉ hợp đồng chính thức.","Tin vào tin đồn sắp niêm yết từ nhóm chat mà không có thông báo chính thức."],"faq":[{"q":"Token được niêm yết trên sàn lớn có an toàn không?","a":"Niêm yết cho thấy token qua được quy trình thẩm định của sàn, nhưng không bảo đảm giá hay chất lượng dự án. Token vẫn có thể giảm mạnh hoặc bị hủy niêm yết sau này."},{"q":"Làm sao biết tin niêm yết là thật?","a":"Chỉ tin thông báo trên trang thông báo chính thức hoặc ứng dụng của sàn. Các nhóm chat và tài khoản giả thường dùng tin niêm yết giả để dụ mua."}],"title":"Niêm yết token là gì? Điều cần biết khi coin lên sàn","description":"Niêm yết token là khi sàn chính thức mở giao dịch một token. Tìm hiểu quy trình, biến động giờ đầu và cách tránh mua đuổi.","related":[["delisting","Hủy niêm yết (delisting)","Hủy niêm yết là việc sàn giao dịch ngừng hỗ trợ một token hoặc cặp giao dịch, thường kèm thời hạn để người dùng đóng vị thế, bán hoặc rút token ra ngoài."],["launchpool","Launchpool","Launchpool là chương trình trên sàn cho phép bạn khóa token như BNB hay stablecoin trong một thời gian để nhận miễn phí token mới của dự án sắp niêm yết."],["liquidity","Thanh khoản (Liquidity)","Thanh khoản là mức độ dễ dàng mua hoặc bán một tài sản với số lượng lớn mà giá không bị đẩy đi nhiều."],["altcoin","Altcoin","Altcoin là cách gọi chung mọi đồng tiền mã hóa không phải Bitcoin, từ các dự án lớn như Ethereum, Solana đến những token nhỏ mới niêm yết."]],"lesson":null,"coin":null,"tool":"/activities","cta":false},"stock-perpetuals":{"slug":"stock-perpetuals","cat":"tokenized-assets","en":"Stock perpetuals","contentLocale":"vi","term":"Hợp đồng vĩnh cửu cổ phiếu (stock perpetuals)","aka":["stock perps","stock perpetuals","perp cổ phiếu","hợp đồng vĩnh cửu chứng khoán"],"short":"Hợp đồng vĩnh cửu cổ phiếu là hợp đồng tương lai không có ngày đáo hạn, theo dõi giá một cổ phiếu hoặc chỉ số chứng khoán và được giao dịch bằng ký quỹ crypto như USDT.","body":[["Cơ chế giống ",["hợp đồng vĩnh cửu","perpetual-futures"]," crypto: bạn mở long hoặc short với ",["đòn bẩy","leverage"],", không sở hữu cổ phiếu, và ",["funding rate","funding-rate"]," định kỳ giữ giá hợp đồng gần ",["giá chỉ số","index-price"],". Một số ",["sàn tập trung","centralized-exchange"]," và ",["perp DEX","perp-dex"]," trên chuỗi đã cung cấp loại sản phẩm này."],"Điểm khác lớn nhất là giờ giao dịch. Thị trường chứng khoán gốc đóng cửa ban đêm, cuối tuần và ngày lễ, nhưng hợp đồng có thể vẫn chạy. Khi đó giá chỉ số có thể dựa trên nguồn giá ngoài giờ hoặc cơ chế nội bộ, và khi sàn chứng khoán mở cửa lại, giá có thể nhảy khoảng mạnh.","Cú nhảy giá lúc mở cửa có thể vượt qua mức cắt lỗ và gây thanh lý ngay. Hãy đọc trang thông số hợp đồng để biết nguồn giá chỉ số, giờ giao dịch, chu kỳ funding và đòn bẩy tối đa."],"example":"Giả sử bạn mở long hợp đồng vĩnh cửu cổ phiếu ABC ở 100 USD với ký quỹ 500 USDT và đòn bẩy 10 lần, vị thế trị giá 5.000 USDT. Cuối tuần, công ty công bố tin xấu. Thứ Hai, cổ phiếu mở cửa ở 91 USD, giảm 9%. Vị thế lỗ 450 USDT, tức 90% ký quỹ, và rất có thể đã chạm giá thanh lý trước khi lệnh cắt lỗ ở 95 USD kịp khớp.","mistakes":["Dùng đòn bẩy cao qua cuối tuần hoặc trước báo cáo kết quả kinh doanh.","Nghĩ lệnh cắt lỗ luôn khớp đúng giá khi thị trường gốc mở cửa với khoảng trống giá.","Không kiểm tra giá chỉ số được lấy từ đâu ngoài giờ giao dịch chứng khoán."],"faq":[{"q":"Giao dịch hợp đồng vĩnh cửu cổ phiếu có sở hữu cổ phiếu không?","a":"Không. Bạn chỉ đặt cược vào biến động giá bằng ký quỹ, không có quyền cổ đông, không nhận cổ tức trực tiếp."},{"q":"Funding rate của hợp đồng cổ phiếu tính thế nào?","a":"Tương tự hợp đồng crypto, dựa trên chênh lệch giữa giá hợp đồng và giá chỉ số. Chu kỳ và công thức khác nhau giữa các sàn, hãy xem trang thông số hợp đồng."}],"title":"Hợp đồng vĩnh cửu cổ phiếu là gì? Stock perps","description":"Stock perpetuals cho phép long, short cổ phiếu bằng USDT với đòn bẩy. Tìm hiểu funding, giờ giao dịch, khoảng trống giá và rủi ro.","related":[["tokenized-stocks","Cổ phiếu token hóa (tokenized stocks)","Cổ phiếu token hóa là token đại diện cho giá trị của một cổ phiếu niêm yết như Apple hay Tesla, thường được bảo chứng bởi cổ phiếu thật do một đơn vị lưu ký nắm giữ."],["perpetual-futures","Hợp đồng tương lai vĩnh cửu (Perpetual)","Hợp đồng tương lai vĩnh cửu (perpetual) là hợp đồng tương lai không có ngày đáo hạn, dùng cơ chế funding rate để giữ giá hợp đồng bám sát giá spot."],["funding-rate","Funding rate (Tỷ lệ funding)","Funding rate là khoản thanh toán định kỳ giữa phe long và phe short trong hợp đồng tương lai vĩnh cửu, giúp giá hợp đồng bám sát giá spot."],["leverage","Đòn bẩy (Leverage)","Đòn bẩy là việc dùng một khoản ký quỹ nhỏ để mở vị thế có giá trị lớn hơn nhiều lần, làm phóng đại cả lợi nhuận lẫn thua lỗ."]],"lesson":null,"coin":null,"tool":"/topics/tokenized-stocks-vs-perpetuals","cta":true}});
